const onSearchInputChange = async (event) => {
  const query = event.target.value.trim();

  if (!query) {
    removeExistingChildren(resultsDiv);
    removeExistingChildren(resultsCountContainer);
    return;
  }

  document.querySelector('.search__container').classList.add('is-loading');

  const minDelay = new Promise((resolve) => {
    setTimeout(resolve, 200);
  });

  try {
    const res = await fetch(
      `${window.location.origin}${
        window.languageCode ? `/${window.languageCode}` : ''
      }/search_json/?${new URLSearchParams({
        query,
      }).toString()}`,
    );
    const data = await res.json();
    injectResultsInHTML(data);
  } catch (err) {
    console.log(err);
    window.alert(`Error: ${err}`);
  } finally {
    await minDelay; // wait for 300ms to pass if fetch was faster
    document.querySelector('.search__container').classList.remove('is-loading');
  }
};
const onSearchInputKeyUp = debounce(onSearchInputChange, 150);

searchInput.addEventListener('keyup', (event) => {
  if (event.key === 'Tab') return;
  onSearchInputKeyUp(event);
});

{# blocking js loaded first to ensure no flash of white on theme detection #}
<script src="{% manifest 'blocking.js' %}"></script>

{% include "components/skip_link.html" %}
{% wagtailuserbar %}

<div class="grid">
    <div class="app__header">
        {# The header only varies by language - the active menu item is highlighted client-side. #}
        {% wagtailcache 86400 header LANGUAGE_CODE %}
            {% header %}
        {% endwagtailcache %}
    </div>

    <div class="app__content">
        <div class="page-tools">
            {% include "components/theme_toggle.html" %}
            {% if page.has_markdown_route %}
                {% include "components/copy_button.html" %}
            {% endif %}
            {# The selector only changes when the page's translations do. #}
            {% wagtailcache 86400 language_selector LANGUAGE_CODE page.id %}
                {% language_selector %}
            {% endwagtailcache %}
        </div>
        <main id="main-content">

    {% if GOOGLE_TAG_MANAGER_ID and not request.is_preview and not is_pattern_library %}
        <!-- Google Tag Manager -->
        <script nonce="{{ csp_nonce }}">(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':
            new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],
                                                      j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src=
                'https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);
        })(window,document,'script','dataLayer','{{ GOOGLE_TAG_MANAGER_ID|escapejs }}');
        </script>
        <!-- End Google Tag Manager -->
    {% endif %}
{% endblock meta_tags %}
{% block body_class %}{{ block.super }}{% if page %}template-{{ page.get_verbose_name|slugify }}{% endif %} {% endblock %}

{% block body_top %}
    {% if GOOGLE_TAG_MANAGER_ID and not request.is_preview and not is_pattern_library %}
        <noscript><iframe src="https://www.googletagmanager.com/ns.html?id=GTM-5XDDLH" height="0" width="0" style="display:none;visibility:hidden"></iframe></noscript>
    {% endif %}

{% if page.video %}
    <div class="home-embed">
        <div class="responsive-object" style="padding-bottom: 56.25%;">
            {# Bare-minimum alternative text for the homepage video. To be replaced with YouTube. #}
            <p id="home-embed-video-description" class="u-sr-only">Promotional homepage video</p>
            <video aria-describedby="home-embed-video-description" preload="none"{% if page.video.thumbnail %} poster="{{ page.video.thumbnail.url }}"{% endif %} controls>
                {% for source in page.video.sources %}
                    <source type="{{ source.type }}" src="{{ source.src }}">
                {% endfor %}
            </video>
        </div>
    </div>
{% endif %}

