    font-weight: 600;
}

@font-face {
    font-family: 'Kumbh Sans';
    src: url('../fonts/KumbhSans-Bold.woff2') format('woff2');
    font-weight: 700;
}
// stylelint-enable scale-unlimited/declaration-strict-value

{% load wagtailcore_tags wagtailimages_tags %}

<div class="highlight{% if image_on_right %} highlight--reverse{% endif %} grid">
    {% image value.image width-1300 class="highlight__image" loading="lazy" %}

    <div class="highlight__content">
        {% if value.meta_icon and value.meta_text %}
            <div class="highlight__meta">
                {% include "patterns/components/icon/icon.html" with icon=value.meta_icon classes="highlight__meta-icon" %}
                <span class="highlight__meta-text heading-four">{{ value.meta_text }}</span>

